sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    //check for existing REG tasks - except for Closed Incomplete
    var existingReg = new GlideRecord('x_1776078_cyber_0_regulatory_notification_task');
    var stateOrQuery = existingReg.addQuery('state', '-5');
    stateOrQuery.addOrCondition('state', '1');
    stateOrQuery.addOrCondition('state', '2');
    stateOrQuery.addOrCondition('state', '3');
    stateOrQuery.addOrCondition('state', '5');
    existingReg.addQuery('parent_cyber_incident', current.sys_id);
    existingReg.addQuery('notification_type', 'asd_soci_notification');
    existingReg.setLimit(1);
    existingReg.query();

    // if task exists, let user know and dont create task
    if (existingReg.next()) {
        gs.addInfoMessage('An active SOCI notification task already exists for this cyber incident - no new task has been created.');

        //if no task exists, create a new one
    } else {
        var newReg = new GlideRecord('x_1776078_cyber_0_regulatory_notification_task');
        newReg.initialize();
        newReg.setValue('parent_cyber_incident', current.sys_id);
        newReg.setValue('notification_type', 'asd_soci_notification');
        newReg.setValue('assignment_group', 'b7aa36d9c3d1431043481cedd40131f1');
        newReg.setValue('state', '-5');
        newReg.setValue('short_description', 'ASD/SOCI notification - ' + current.getValue('number'));
        newReg.setValue('soci_classification', current.getValue('suggested_soci_classification'));
        newReg.insert();
        current.work_notes = newReg.number + ': ' + newReg.getDisplayValue('notification_type') + ' created.';
        current.update();
    }

})(current, previous);
